-- PLUSSING-3 (2026-10-29, charter pillar autonomy). Builds roadmap item PLUS-3 of docs/PLUSSING.md (PLUSSING-1, PR 5237) and the mechanical half of PLUS-4.
-- Owner prompt 2026-10-29 (Rowan): keep products such as me.q08.org improving automatically, without the user prompting; plussing as a fleet philosophy.
--
-- WHAT: nine steps are appended to the hourly management-personas workflow (fleet_tasks). Each tick, for up to 3 products a day (ops_config
-- product_plus_daily_cap, default 3) taken in the order of v_product_plus_due (longest since the last plus first, with nothing in flight and not resting), the
-- product's program manager asks the Cloudflare agent (cf_agent_requests, instance roadmap-<program>-plus-<product>-<day>) for ONE plus (or a simplify pass every
-- fifth cycle), with the product's earlier plus_ledger rows in the prompt so each plus builds on the last, and with the predicted metric in the reply. The
-- answer rides the ROADMAP-ORIGINATE-1 path unchanged (rm-parse, rm-reject, rm-file, rm-track, rm-deployed*): proposal, validation, ROADMAP-1 issue with
-- code-task and code-anchor, code loop, canonical deploy with canary and revert, close with the pull request. pl-ledger/pl-sync mirror each proposal into plus_ledger,
-- pl-deployed sets product_registry.last_plus_at and the simplify counter when a plus is live, pl-log writes persona_actions product-plus, pl-metric and pl-brief report.
-- Not built here (stay planned in roadmap_implementation): PLUS-2 usage signal, the metric verify-and-keep revert (PLUS-4 second half), the digest and /plus page (PLUS-5),
-- rest after three misses (PLUS-6).
-- Personal products: the roadmap validator refuses personal-* paths. Rowan asked for me.q08.org by name, so rm-reject is amended to allow personal-* for instances
-- containing -plus-; the prompt forbids reading personal data. Control plane, .github and short anchors stay rejected; control-plane products are not asked at all.
-- research-gateway pointed at qnfo-router, a directory that does not exist; ai.qnfo.org is served by qnfo-ai (docs/DOMAINS.md), so the registry row is corrected.
-- Stop: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('product_plus', 'off');
-- Verify after apply: SELECT * FROM plus_ledger ORDER BY id DESC;  SELECT * FROM v_product_plus_due;  SELECT instance, status FROM cf_agent_requests WHERE instance LIKE 'roadmap-%-plus-%';
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261029_plus3_workflow
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT definition FROM bak_20261029_plus3_workflow WHERE id = 'management-personas'), version = version + 1 WHERE id = 'management-personas'; INSERT OR REPLACE INTO ops_config (key, value) VALUES ('product_plus', 'off');

CREATE TABLE IF NOT EXISTS bak_20261029_plus3_workflow AS SELECT id, definition, version FROM fleet_tasks WHERE id = 'management-personas';

INSERT OR IGNORE INTO ops_config (key, value) VALUES ('product_plus', 'on');
INSERT OR IGNORE INTO ops_config (key, value) VALUES ('product_plus_daily_cap', '3');

UPDATE product_registry SET worker = 'qnfo-ai' WHERE product = 'research-gateway' AND worker = 'qnfo-router';

-- personal-* worker files are valid plus targets (instances containing -plus-); everything else the validator refused is still refused
UPDATE fleet_tasks
SET definition = replace(definition, 'instr(roadmap_proposals.path, d.value) = 1)', 'instr(roadmap_proposals.path, d.value) = 1 AND NOT (d.value = ''personal-'' AND roadmap_proposals.request_instance LIKE ''roadmap-%-plus-%''))'),
  version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE id = 'management-personas' AND instr(definition, 'd.value = ''personal-''') = 0 AND instr(definition, 'instr(roadmap_proposals.path, d.value) = 1)') > 0;

UPDATE fleet_tasks
SET definition = json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(definition, '$.steps[#]', json('{"type": "sql", "name": "pl-research", "db": "AUDIT", "sql": "INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:'' || r.program_code, ''run'', ''You are the product manager of '' || r.product || '' ('' || COALESCE(r.host, '''') || ''), which is for: '' || COALESCE(r.what_for, '''') || ''. It runs in the QNFO fleet (repository QNFO/qnfo-workers, Cloudflare Workers plus the D1 database qnfo-audit). Your job is to PLUS it, the Pixar practice of making an already-good thing better by adding to it, never tearing it down. Keep what works, say yes-and, and never offer a critique without the change that answers it. The code is '' || r.worker || ''/worker.js: read it from the side of its user (pages, routes, replies, empty states, failure paths). Usage signal: '' || COALESCE(r.usage_metric, ''none yet'') || ''. Quality measure: '' || COALESCE(r.quality_measure, ''none yet, so a measurement plus is a good first move'') || ''. Plusses already made (build on them, never repeat them): '' || COALESCE((SELECT group_concat(substr(title, 1, 80) || '' ['' || status || '']'', ''; '') FROM (SELECT title, status FROM plus_ledger WHERE product = r.product ORDER BY id DESC LIMIT 8)), ''none yet, this is the first'') || ''. '' || CASE WHEN d.next_kind = ''simplify'' THEN ''This cycle is a SIMPLIFY pass: remove or fold one piece of clutter that makes the product harder to use, without removing anything a user relies on. '' ELSE ''Propose exactly one plus: the smallest reversible addition that builds on what is there. '' END || ''Candidates: a rough edge in a recent plus, a slow or empty or confusing state, the affordance the user would reach for next, a failure path that says nothing, a small delight. Pick the best ratio of user value to size, one worker file. Never read or quote personal data tables of the owner; improve the behaviour of the product only. Reply in exactly this form, each on its own line:'' || char(10) || ''TITLE: <under 80 characters>'' || char(10) || ''WHY: <who notices it, the metric you predict moves, in which direction and by how much, under 80 words>'' || char(10) || ''code-task: repo=qnfo-workers path='' || r.worker || ''/worker.js'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''roadmap-'' || r.program_code || ''-plus-'' || r.product || ''-'' || strftime(''%Y%m%d'', ''now''), ''medium'' FROM v_product_plus_due d JOIN product_registry r ON r.product = d.product WHERE d.in_flight = 0 AND r.worker IS NOT NULL AND NOT EXISTS (SELECT 1 FROM json_each(''[\"qnfo-fleet-control\",\"qnfo-ops\",\"qnfo-deploy-guard\",\"qnfo-containers-pilot\",\"qnfo-autonomy-scorer\",\"qnfo-observability\",\"qnfo-code-orchestrator\",\"qnfo-code-agent\"]'') c WHERE c.value = r.worker) AND NOT EXISTS (SELECT 1 FROM roadmap_proposals p WHERE p.request_instance LIKE ''roadmap-%-plus-'' || r.product || ''-%'' AND p.status IN (''proposed'', ''filed'', ''building'')) AND NOT EXISTS (SELECT 1 FROM cf_agent_requests q WHERE q.instance = ''roadmap-'' || r.program_code || ''-plus-'' || r.product || ''-'' || strftime(''%Y%m%d'', ''now'') AND (q.status IN (''queued'', ''running'') OR (q.status = ''done'' AND COALESCE(q.result, '''') NOT LIKE ''(the model returned no text)%'' AND COALESCE(q.result, '''') <> ''''))) AND (SELECT COUNT(*) FROM cf_agent_requests q WHERE q.instance LIKE ''roadmap-%-plus-%-'' || strftime(''%Y%m%d'', ''now'')) < COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''product_plus_daily_cap''), 3) AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''product_plus''), ''on'') <> ''off'' ORDER BY d.hours_since_plus DESC LIMIT 3"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-ledger", "db": "AUDIT", "sql": "INSERT INTO plus_ledger (product, kind, title, evidence, predicted_outcome, issue_id, status) SELECT substr(p.request_instance, instr(p.request_instance, ''-plus-'') + 6, length(p.request_instance) - instr(p.request_instance, ''-plus-'') - 14), CASE WHEN COALESCE((SELECT r.pluses_since_simplify FROM product_registry r WHERE r.product = substr(p.request_instance, instr(p.request_instance, ''-plus-'') + 6, length(p.request_instance) - instr(p.request_instance, ''-plus-'') - 14)), 0) >= 4 THEN ''simplify'' ELSE ''plus'' END, p.title, ''proposal #'' || p.id || '' ('' || p.request_instance || ''): '' || substr(p.path, 1, 80), substr(p.rationale, 1, 400), p.issue_id, ''proposed'' FROM roadmap_proposals p WHERE p.request_instance LIKE ''roadmap-%-plus-%'' AND p.status <> ''rejected'' AND EXISTS (SELECT 1 FROM product_registry r WHERE r.product = substr(p.request_instance, instr(p.request_instance, ''-plus-'') + 6, length(p.request_instance) - instr(p.request_instance, ''-plus-'') - 14)) AND NOT EXISTS (SELECT 1 FROM plus_ledger l WHERE l.evidence LIKE ''proposal #'' || p.id || '' (%'')"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-sync", "db": "AUDIT", "sql": "UPDATE plus_ledger SET status = CASE (SELECT p.status FROM roadmap_proposals p WHERE plus_ledger.evidence LIKE ''proposal #'' || p.id || '' (%'') WHEN ''building'' THEN ''building'' WHEN ''deployed'' THEN ''deployed'' WHEN ''rejected'' THEN ''rejected'' ELSE status END, issue_id = COALESCE((SELECT p.issue_id FROM roadmap_proposals p WHERE plus_ledger.evidence LIKE ''proposal #'' || p.id || '' (%''), issue_id), pr_url = COALESCE((SELECT p.pr_url FROM roadmap_proposals p WHERE plus_ledger.evidence LIKE ''proposal #'' || p.id || '' (%''), pr_url), decided_at = CASE WHEN (SELECT p.status FROM roadmap_proposals p WHERE plus_ledger.evidence LIKE ''proposal #'' || p.id || '' (%'') IN (''deployed'', ''rejected'') THEN strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') ELSE decided_at END WHERE status IN (''proposed'', ''building'') AND EXISTS (SELECT 1 FROM roadmap_proposals p WHERE plus_ledger.evidence LIKE ''proposal #'' || p.id || '' (%'')"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-rejected", "db": "AUDIT", "sql": "UPDATE plus_ledger SET status = ''rejected'', outcome = (SELECT p.outcome FROM roadmap_proposals p WHERE plus_ledger.evidence LIKE ''proposal #'' || p.id || '' (%'') WHERE status = ''rejected'' AND outcome IS NULL"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-deployed", "db": "AUDIT", "sql": "UPDATE product_registry SET last_plus_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), misses_in_row = 0, pluses_since_simplify = CASE WHEN EXISTS (SELECT 1 FROM plus_ledger l WHERE l.product = product_registry.product AND l.status = ''deployed'' AND l.kind = ''simplify'' AND l.outcome IS NULL) THEN 0 ELSE pluses_since_simplify + 1 END WHERE EXISTS (SELECT 1 FROM plus_ledger l WHERE l.product = product_registry.product AND l.status = ''deployed'' AND l.outcome IS NULL)"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-deployed-mark", "db": "AUDIT", "sql": "UPDATE plus_ledger SET outcome = ''deployed, merged and verified live'' WHERE status = ''deployed'' AND outcome IS NULL"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''product-manager:'' || l.product, ''product-plus'', l.issue_id, ''plus #'' || l.id, l.status, l.kind || '': '' || l.title FROM plus_ledger l WHERE l.issue_id IS NOT NULL AND l.status IN (''building'', ''deployed'') AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.kind = ''product-plus'' AND a.issue_id = l.issue_id AND a.to_value = l.status)"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-metric", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM plus_ledger WHERE status = ''deployed'' AND decided_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), state = ''MEASURED'' WHERE metric = ''product_plus_deployed_7d''"}')), '$.steps[#]', json('{"type": "sql", "name": "pl-brief", "db": "AUDIT", "sql": "UPDATE persona_briefs SET summary = summary || '' Product plussing: '' || (SELECT COUNT(*) FROM product_registry WHERE state = ''active'') || '' products, '' || (SELECT COUNT(*) FROM plus_ledger WHERE status IN (''proposed'', ''building'')) || '' plusses in flight, '' || (SELECT COUNT(*) FROM plus_ledger WHERE status = ''deployed'' AND decided_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'')) || '' deployed in 7 days'' || COALESCE('' (latest: '' || (SELECT product || '': '' || title FROM plus_ledger WHERE status = ''deployed'' ORDER BY decided_at DESC LIMIT 1) || '')'', '''') || ''.'' WHERE persona_key = ''portfolio-manager'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations) AND summary NOT LIKE ''%Product plussing:%''"}')),
  version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE id = 'management-personas' AND instr(definition, '"pl-research"') = 0;

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, target, owner, disposition_actor, refresh_cadence, state) VALUES
  ('product_plus_deployed_7d', 'operational', 'target',
   'plusses (plus_ledger rows) merged and verified live in the last 7 days. Trigger exemption: the product managers research, file and close these items themselves every hour (PLUSSING-3) and the portfolio brief reports the count, which is the action a trigger would take',
   'qnfo-audit.plus_ledger (PLUSSING-3), written hourly by fleet_tasks management-personas', '>= 3 a week', 'qnfo-fleet-control', 'agent:management-personas', 'hourly', 'PENDING');

UPDATE roadmap_implementation SET status = 'built', evidence = 'migrations/2026-10-29-plussing-3.sql: steps pl-research..pl-brief in fleet_tasks management-personas' WHERE source = 'plussing-2026' AND item = 'PLUS-3';

INSERT OR IGNORE INTO capability_ledger (capability, provenance, prerequisites, reliability, acquired_at, evidence)
VALUES ('product-plussing', 'migrations/2026-10-29-plussing-3.sql (PLUSSING-3)', 'product_registry, plus_ledger, fleet_tasks management-personas, ROADMAP-ORIGINATE-1 path, cf_agent_requests, code loop, canonical deploy', 0.5, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  'each due product asks the Cloudflare agent for one plus that builds on its earlier plusses; the plus is built, deployed with canary and revert, and closed with the pull request');

